-- EvidenceOS initial metadata schema.
-- Apply with psql -v ON_ERROR_STOP=1 -f migrations/0001_initial_schema.sql.
-- The application must set LOCAL evidenceos.tenant_id after authenticating a
-- request. The database role used by the application must not be a superuser
-- and must not have BYPASSRLS. IDs are generated by the application.

BEGIN;

CREATE TABLE tenants (
    id uuid PRIMARY KEY,
    name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id)
);

CREATE TABLE collections (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, name)
);

CREATE TABLE documents (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    collection_id uuid NOT NULL,
    display_name text NOT NULL,
    status text NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'processing', 'ready', 'failed', 'deleting', 'deleted')),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, collection_id)
        REFERENCES collections(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE document_versions (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    document_id uuid NOT NULL,
    version_number integer NOT NULL CHECK (version_number > 0),
    object_key text NOT NULL,
    content_sha256 char(64) NOT NULL,
    media_type text NOT NULL,
    byte_size bigint NOT NULL CHECK (byte_size >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, document_id, version_number),
    FOREIGN KEY (tenant_id, document_id)
        REFERENCES documents(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE chunks (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    document_version_id uuid NOT NULL,
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    content text NOT NULL,
    content_sha256 char(64) NOT NULL,
    page_number integer CHECK (page_number IS NULL OR page_number > 0),
    start_offset integer NOT NULL CHECK (start_offset >= 0),
    end_offset integer NOT NULL CHECK (end_offset >= start_offset),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    UNIQUE (tenant_id, document_version_id, ordinal),
    FOREIGN KEY (tenant_id, document_version_id)
        REFERENCES document_versions(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE jobs (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    document_version_id uuid,
    job_type text NOT NULL,
    status text NOT NULL DEFAULT 'queued'
        CHECK (status IN ('queued', 'running', 'retry_wait', 'completed', 'failed', 'cancelled')),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts integer NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
    available_at timestamptz NOT NULL DEFAULT now(),
    lease_expires_at timestamptz,
    last_error_code text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, document_version_id)
        REFERENCES document_versions(tenant_id, id) ON DELETE CASCADE
);

CREATE INDEX jobs_claim_idx ON jobs (available_at, created_at)
    WHERE status IN ('queued', 'retry_wait');

CREATE TABLE answers (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    collection_id uuid NOT NULL,
    question text NOT NULL,
    answer_text text,
    status text NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'completed', 'failed')),
    retrieval_config_id text,
    generation_provider text,
    generation_model text,
    prompt_version text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, collection_id)
        REFERENCES collections(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE citations (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    chunk_id uuid NOT NULL,
    start_offset integer NOT NULL CHECK (start_offset >= 0),
    end_offset integer NOT NULL CHECK (end_offset >= start_offset),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, answer_id) REFERENCES answers(tenant_id, id) ON DELETE CASCADE,
    FOREIGN KEY (tenant_id, chunk_id) REFERENCES chunks(tenant_id, id) ON DELETE RESTRICT
);

CREATE TABLE claims (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    claim_text text NOT NULL,
    answer_start_offset integer NOT NULL CHECK (answer_start_offset >= 0),
    answer_end_offset integer NOT NULL CHECK (answer_end_offset >= answer_start_offset),
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, answer_id) REFERENCES answers(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE verifications (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    claim_id uuid NOT NULL,
    verdict text NOT NULL CHECK (
        verdict IN ('supported', 'contradicted', 'insufficient_evidence', 'review_required')
    ),
    status text NOT NULL DEFAULT 'completed'
        CHECK (status IN ('pending', 'completed', 'failed')),
    verifier_id text,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (tenant_id, id),
    FOREIGN KEY (tenant_id, claim_id) REFERENCES claims(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE evidence_links (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL,
    verification_id uuid NOT NULL,
    chunk_id uuid NOT NULL,
    relation text NOT NULL CHECK (relation IN ('supports', 'contradicts', 'context')),
    start_offset integer NOT NULL CHECK (start_offset >= 0),
    end_offset integer NOT NULL CHECK (end_offset >= start_offset),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (tenant_id, verification_id)
        REFERENCES verifications(tenant_id, id) ON DELETE CASCADE,
    FOREIGN KEY (tenant_id, chunk_id) REFERENCES chunks(tenant_id, id) ON DELETE RESTRICT
);

CREATE TABLE audit_events (
    id uuid PRIMARY KEY,
    tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    actor_id text,
    action text NOT NULL,
    resource_type text NOT NULL,
    resource_id uuid,
    request_id text,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX documents_collection_status_idx ON documents (tenant_id, collection_id, status);
CREATE INDEX versions_document_idx ON document_versions (tenant_id, document_id, version_number DESC);
CREATE INDEX chunks_version_idx ON chunks (tenant_id, document_version_id, ordinal);
CREATE INDEX answers_collection_created_idx ON answers (tenant_id, collection_id, created_at DESC);
CREATE INDEX citations_answer_idx ON citations (tenant_id, answer_id);
CREATE INDEX claims_answer_idx ON claims (tenant_id, answer_id);
CREATE INDEX verifications_claim_idx ON verifications (tenant_id, claim_id, created_at DESC);
CREATE INDEX evidence_verification_idx ON evidence_links (tenant_id, verification_id);
CREATE INDEX audit_tenant_created_idx ON audit_events (tenant_id, created_at DESC);

-- RLS is a second barrier against accidentally unscoped queries. Authentication
-- must establish this setting on every transaction; it is not identity proof
-- against a compromised application role that can choose arbitrary tenant IDs.
DO $$
DECLARE
    table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'collections', 'documents', 'document_versions', 'chunks', 'jobs',
        'answers', 'citations', 'claims', 'verifications', 'evidence_links', 'audit_events'
    ] LOOP
        EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', table_name);
        EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', table_name);
        EXECUTE format(
            'CREATE POLICY tenant_isolation ON %I USING (tenant_id::text = current_setting(''evidenceos.tenant_id'', true)) WITH CHECK (tenant_id::text = current_setting(''evidenceos.tenant_id'', true))',
            table_name
        );
    END LOOP;
END $$;

ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenants
    USING (id::text = current_setting('evidenceos.tenant_id', true))
    WITH CHECK (id::text = current_setting('evidenceos.tenant_id', true));

COMMIT;
